{
  "src/protocol_adapter.ts": "import { WorldProtocol } from './types';
import { applyResetFenOperation } from './vok/rules';

export interface Operation {
  type: string;
  [key: string]: any;
}

export interface EntityState {
  fen: string;
  [key: string]: any;
}

export interface WorldSnapshot {
  entities: Map<string, EntityState>;
  [key: string]: any;
}

class ProtocolImpl implements WorldProtocol {
  private state: WorldSnapshot = {
    entities: new Map(),
  };

  reset(): void {
    this.state = {
      entities: new Map(),
    };
  }

  applyOperation(operation: Operation): void {
    if (operation.type === 'resetFen') {
      applyResetFenOperation(this.state, operation);
    }
  }

  getEntityState(entityId: string): EntityState | undefined {
    return this.state.entities.get(entityId);
  }

  toAbstractSnapshot(): WorldSnapshot {
    return {
      entities: new Map(this.state.entities),
    };
  }
}

export const protocol: WorldProtocol = new ProtocolImpl();
",
  "src/vok/rules.ts": "import { WorldSnapshot, Operation } from '../protocol_adapter';

export function applyResetFenOperation(
  state: WorldSnapshot,
  operation: Operation
): void {
  const entityId = operation.entityId;

  if (!state.entities.has(entityId)) {
    state.entities.set(entityId, { fen: 'nim' });
    return;
  }

  const entity = state.entities.get(entityId);
  if (entity && entity.fen === 'pex') {
    entity.fen = 'nim';
  }
}
",
  "src/types.ts": "import { Operation, EntityState, WorldSnapshot } from './protocol_adapter';

export interface WorldProtocol {
  reset(): void;
  applyOperation(operation: Operation): void;
  getEntityState(entityId: string): EntityState | undefined;
  toAbstractSnapshot(): WorldSnapshot;
}
"
